import numpy as np
from PIL import Image
a=np.array(Image.open('first_frame.png')).astype(int)
mean=a.mean(2)
for thr in (25,40,60):
  m=mean<thr
  H,W=m.shape; seen=np.zeros_like(m,bool); comps=[]
  for y in range(H):
    for x in range(W):
      if m[y,x] and not seen[y,x]:
        stack=[(y,x)];seen[y,x]=1;pts=[]
        while stack:
          cy,cx=stack.pop();pts.append((cy,cx))
          for dy in(-1,0,1):
            for dx in(-1,0,1):
              ny,nx=cy+dy,cx+dx
              if 0<=ny<H and 0<=nx<W and m[ny,nx] and not seen[ny,nx]:
                seen[ny,nx]=1;stack.append((ny,nx))
        comps.append(pts)
  comps.sort(key=len,reverse=True)
  print(\"=== threshold\",thr)
  for pts in comps[:8]:
    yy=np.array([p[0] for p in pts]);xx=np.array([p[1] for p in pts])
    print(\"n\",len(pts),\"x\",xx.min(),xx.max(),\"y\",yy.min(),yy.max())
EOF"

